// @otthi-module-body
  function useActivity(type,house){
    if(type==='bed'){
      player.sitUntil=performance.now()+1400;state.needs.energy=100;state.needs.hunger=Math.max(0,state.needs.hunger-4);setFlag('slept');addXP(20);toast('Você dormiu e salvou o jogo.','good');saveState(true);
    }else if(type==='sofa'){
      player.sitUntil=performance.now()+2400;state.needs.fun=clamp(state.needs.fun+20,0,100);toast('Sentou no sofá.','good');addXP(5);
    }else if(type==='tv'){
      player.sitUntil=performance.now()+3000;state.needs.fun=clamp(state.needs.fun+34,0,100);state.needs.energy=clamp(state.needs.energy-3,0,100);toast(`Assistindo ao desenho de ${playerDisplayName()}!`,'good');addXP(8);
    }else if(type==='fridge'){
      openModal('Geladeira',`<p>Comida disponível: <b>${state.inventory.food}</b></p><div class="modal-actions"><button class="btn primary" data-eat>Comer lanche</button><button class="btn" data-close>Fechar</button></div>`,root=>{
        $('[data-eat]',root).onclick=()=>{if(state.inventory.food<=0){toast('A geladeira está vazia.','warn');return;}state.inventory.food--;state.needs.hunger=clamp(state.needs.hunger+32,0,100);setFlag('ateMeal');addXP(12);saveState();closeModal();toast('Lanche delicioso!','good');};$('[data-close]',root).onclick=closeModal;
      });
    }else if(type==='stove'){
      openModal('Cozinha',`<p>Cozinhar custa 1 comida e recupera muita fome.</p><div class="modal-actions"><button class="btn primary" data-cook>Cozinhar refeição</button><button class="btn" data-close>Cancelar</button></div>`,root=>{
        $('[data-cook]',root).onclick=()=>{if(state.inventory.food<=0){toast('Você precisa comprar ou colher comida.','warn');return;}state.inventory.food--;state.stats.cooked++;trackDaily('cook',1);state.needs.hunger=100;state.needs.fun=clamp(state.needs.fun+8,0,100);setFlag('ateMeal');addXP(20);saveState();closeModal();toast('Refeição pronta!','good');};$('[data-close]',root).onclick=closeModal;
      });
    }else if(type==='sink'){
      if(state.inventory.water>0)state.inventory.water--;state.needs.hunger=clamp(state.needs.hunger+5,0,100);state.needs.hygiene=clamp(state.needs.hygiene+8,0,100);toast('Bebeu água.','good');saveState();
    }else if(type==='shower'){
      state.needs.hygiene=100;state.needs.energy=clamp(state.needs.energy-2,0,100);player.sitUntil=performance.now()+1800;toast('Banho tomado!','good');addXP(8);saveState();
    }else if(type==='chest')openHomeChest();
    else if(type==='shop')openShop();
    else if(type==='workshop')openWorkshop();
    else if(type==='wardrobe')openAvatarStudio();
    else if(type==='school'){if(state.career.activeJob?.id==='teacher')openTeacherJobLesson(house);else if(window.OTTHI_TIA_THAMIS?.open)window.OTTHI_TIA_THAMIS.open('welcome');else openEducationHub(String(state.learning.lastLesson||'math').split('-')[0]);}
    else if(type==='police'){if(state.career.activeJob?.id==='police')toast('Patrulha ativa: siga os pontos marcados no GPS.','good',2200);else openSafetyLesson('station');}
    else if(type==='firestation')openFireStationDesk();
    updateHUD();
  }
  function openShop(){
    ensureWorldEvolutionState?.();
    const items=[
      {name:'Comida',price:15,key:'food',amount:2,icon:'🍎',group:'Consumíveis'},
      {name:'Água',price:8,key:'water',amount:2,icon:'💧',group:'Consumíveis'},
      {name:'Iscas',price:12,key:'bait',amount:5,icon:'🪱',group:'Pesca'},
      {name:'Sementes',price:10,key:'seeds',amount:6,icon:'🌱',group:'Fazenda'},
      {name:'Trigo',price:14,key:'wheat',amount:2,icon:'🌾',group:'Fazenda'},
      {name:'Cenouras',price:14,key:'carrots',amount:2,icon:'🥕',group:'Fazenda'},
      {name:'Argila',price:20,key:'clay',amount:2,icon:'🟫',group:'Materiais'},
      {name:'Cristal',price:80,key:'crystals',amount:1,icon:'💎',group:'Especial'},
      {name:'Vara de pesca',price:65,key:'fishingRod',amount:1,icon:'🎣',group:'Pesca',unique:true},
      {name:'Madeira',price:18,key:'wood',amount:3,icon:'🪵',group:'Materiais'},
      {name:'Pedra',price:18,key:'stone',amount:3,icon:'🪨',group:'Materiais'},
      {name:'Blocos',price:25,key:'blocks',amount:4,icon:'🧱',group:'Construção'},
      {name:'Cercas',price:20,key:'fences',amount:3,icon:'🪵',group:'Construção'},
      {name:'Machado',price:45,tool:'axe',icon:'🪓',group:'Ferramentas'},
      {name:'Picareta',price:48,tool:'pickaxe',icon:'⛏️',group:'Ferramentas'},
      {name:'Balde',price:32,tool:'bucket',icon:'🪣',group:'Ferramentas'},
      {name:'Enxada',price:38,tool:'hoe',icon:'🧑‍🌾',group:'Ferramentas'},
      {name:'Pá',price:35,tool:'shovel',icon:'🪏',group:'Ferramentas'}
    ];
    const cards=items.map((item,i)=>{const owned=item.tool&&state.tools.owned.includes(item.tool);const unique=item.unique&&(state.inventory[item.key]||0)>0;return `<button class="choice shop-choice ${owned||unique?'owned':''}" data-buy="${i}" ${owned||unique?'disabled':''}><b>${item.icon} ${item.name}</b><span>${owned||unique?'Já possui':`${item.price} moedas — ${item.tool?'ferramenta':`+${item.amount}`}`}</span><small>${item.group}</small></button>`;}).join('');
    openModal('Mercadinho da Vila',`<div class="shop-wallet"><span>🪙 Moedas</span><b>${state.profile.coins}</b></div><p class="shop-help">Todos os itens essenciais podem ser comprados aqui, mas também podem ser obtidos jogando, coletando, cavando, plantando e pescando.</p><div class="choice-grid shop-complete-grid">${cards}</div>`,root=>{
      $$('[data-buy]',root).forEach(btn=>btn.onclick=()=>{const item=items[Number(btn.dataset.buy)];if(!item||btn.disabled)return;if(state.profile.coins<item.price){toast('Moedas insuficientes.','warn');return;}addCoins(-item.price);if(item.tool){state.tools.owned=[...new Set([...(state.tools.owned||[]),item.tool])];state.tools.equipped=item.tool;refreshEquippedToolVisual();}else state.inventory[item.key]=(state.inventory[item.key]||0)+item.amount;addXP(5);saveState(true);updateHUD();closeModal();toast(`${item.name} adquirido!`,'good');});
    });
  }
  const DIGITAL_PROJECT_TYPES={
    pwa:{icon:'📱',name:'Site / PWA',summary:'Experiência mobile, instalação, offline e publicação.',goals:['Criar presença digital e atendimento','Montar inscrição ou catálogo online','Transformar um processo em experiência PWA'],best:['Mapear o fluxo principal e o usuário antes da tela.','Mobile-first, estados vazios/erro e persistência clara.','Implementar o fluxo crítico primeiro e medir desempenho.']},
    saas:{icon:'🧩',name:'Sistema / SaaS',summary:'Perfis, regras de negócio, dados e operação.',goals:['Organizar ordens de serviço e clientes','Controlar estoque, cadastro e histórico','Criar painel operacional com perfis de acesso'],best:['Definir perfis, regras e o que cada usuário pode fazer.','Separar interface, regra de negócio e persistência.','Implementar por fluxo completo, incluindo validação e auditoria.']},
    automation:{icon:'⚙️',name:'Automação inteligente',summary:'Evento, regra, ação e rastreabilidade.',goals:['Eliminar tarefa manual repetitiva','Criar alerta quando uma condição acontecer','Integrar etapas de um processo operacional'],best:['Descrever gatilho, condição, exceção e resultado esperado.','Projetar idempotência, confirmação e registro de execução.','Automatizar primeiro o caminho seguro e tratar falhas explicitamente.']},
    game:{icon:'🎮',name:'Jogo / Experiência',summary:'Loop jogável, progressão, feedback e performance.',goals:['Criar uma missão educativa jogável','Montar um minijogo com progressão','Criar experiência interativa para treinamento'],best:['Definir objetivo, ação do jogador e condição de vitória.','Prototipar o loop jogável antes de adicionar decoração.','Medir resposta dos controles, feedback e custo por frame.']},
    dashboard:{icon:'📊',name:'Painel / Dados',summary:'Indicadores acionáveis, filtros e leitura rápida.',goals:['Acompanhar operação em tempo real','Comparar desempenho e identificar gargalos','Criar painel de gestão para tomada de decisão'],best:['Definir quais decisões o painel precisa permitir.','Organizar hierarquia: resumo, exceções, detalhe e ação.','Validar fonte dos dados e evitar consultas repetidas sem necessidade.']}
  };
  const DIGITAL_PROJECT_CLIENTS=['SOS Valêncio','Otton Connect','OTTOVIAS','Mercadinho da Vila','Equipe de Corrida','Prefeitura da Vila'];
  function ensureDigitalStudioState(){state.digitalStudio=state.digitalStudio||{projects:[],delivered:0,created:0,portfolio:[],lastProjectAt:0};state.digitalStudio.projects=Array.isArray(state.digitalStudio.projects)?state.digitalStudio.projects:[];state.digitalStudio.portfolio=Array.isArray(state.digitalStudio.portfolio)?state.digitalStudio.portfolio:[];return state.digitalStudio;}
  function digitalProjectById(id){return ensureDigitalStudioState().projects.find(p=>p.id===id)||null;}
  function digitalPhaseName(index){return['Briefing','Arquitetura / UX','Implementação','Testes','Entrega'][Math.max(0,Math.min(4,Number(index)||0))];}
  function digitalProjectStatus(project){if(project.status==='delivered')return'Entregue';return `${digitalPhaseName(project.phase)} • qualidade ${Math.round(project.quality||0)}%`;}
  function openThiaguinhoPerformanceAudit(){
    const d=typeof runtimeDiagnostics==='function'?runtimeDiagnostics():null,fps=Number(d?.fps||0),calls=Number(d?.drawCalls||0),tri=Number(d?.triangles||0),tier=typeof qualityTier==='function'?qualityTier():'n/d';
    const findings=[];if(d){if(fps&&fps<32)findings.push('FPS baixo: priorizar qualidade automática/econômica e reduzir trabalho invisível.');else findings.push('FPS atual sem alerta crítico nesta amostra.');if(calls>260)findings.push('Draw calls elevados: reutilizar materiais e agrupar decoração repetida.');if(tri>260000)findings.push('Muitos triângulos: manter LOD/culling agressivo no celular.');if(Number(d?.culling?.dynamicHidden||0)>0)findings.push(`Culling ativo: ${d.culling.dynamicHidden} objeto(s) dinâmico(s) fora do orçamento visual.`);}else findings.push('Diagnóstico técnico ainda não está disponível nesta tela.');
    openModal('thIAguinho • Auditoria do OTTHI World',`<div class="dialogue-box"><b>Diagnóstico baseado no runtime desta partida</b><p>Não é texto fixo: estes números vêm do jogo que está rodando agora.</p></div><div class="resource-summary"><span>🎞️ ${fps?fps.toFixed(1):'n/d'} FPS</span><span>🧱 ${calls||0} draw calls</span><span>🔺 ${tri||0} triângulos</span><span>⚙️ ${escapeHtml(String(tier))}</span></div><div class="choice-grid">${findings.map(x=>`<div class="choice"><b>🔎 Análise</b><span>${escapeHtml(x)}</span></div>`).join('')}</div><div class="modal-actions"><button class="btn primary" data-digital-back>Voltar ao estúdio</button></div>`,root=>$('[data-digital-back]',root).onclick=openThiaguinhoStudio);
  }
  function openThiaguinhoStudio(){
    const studio=ensureDigitalStudioState(),active=studio.projects.filter(p=>p.status!=='delivered'),delivered=studio.projects.filter(p=>p.status==='delivered'),cards=active.length?active.map(p=>`<button class="choice" data-project-open="${escapeHtml(p.id)}"><b>${DIGITAL_PROJECT_TYPES[p.type]?.icon||'💻'} ${escapeHtml(p.title)}</b><span>${escapeHtml(digitalProjectStatus(p))}</span><small>${escapeHtml(p.client)} • ${escapeHtml(p.goal)}</small></button>`).join(''):'<div class="choice"><b>📂 Nenhum projeto em andamento</b><span>Crie um projeto e conduza briefing, arquitetura, implementação, testes e entrega.</span></div>';
    openModal('thIAguinho Soluções Digitais',`<div class="dialogue-box"><img src="assets/branding/thiaguinho-solucoes-digitais.png" alt="thIAguinho Soluções Digitais" style="display:block;width:min(260px,82%);height:auto;margin:0 auto 12px;background:#07101d;padding:10px;border-radius:12px"><b>Laboratório de projetos</b><p>Aqui você realmente cria e conduz projetos digitais dentro do OTTHI World. Cada projeto fica salvo e precisa passar pelas etapas de um trabalho real.</p></div><div class="resource-summary"><span>🧩 ${studio.created||0} criados</span><span>✅ ${studio.delivered||0} entregues</span><span>📁 ${active.length} em andamento</span></div><div class="choice-grid"><button class="choice" data-digital="new"><b>➕ Criar novo projeto</b><span>Escolher solução, cliente e objetivo</span></button><button class="choice" data-digital="audit"><b>⚡ Auditar OTTHI World</b><span>Ler FPS, draw calls e orçamento de renderização desta partida</span></button>${cards}</div>${delivered.length?`<small>Portfólio recente: ${delivered.slice(-3).map(p=>escapeHtml(p.title)).join(' • ')}</small>`:''}`,root=>{
      root.onclick=e=>{const newBtn=e.target.closest('[data-digital="new"]'),audit=e.target.closest('[data-digital="audit"]'),project=e.target.closest('[data-project-open]');if(newBtn){openDigitalProjectType();return;}if(audit){openThiaguinhoPerformanceAudit();return;}if(project)openDigitalProject(project.dataset.projectOpen);};
    });
  }
  function openDigitalProjectType(){
    const studio=ensureDigitalStudioState(),active=studio.projects.filter(p=>p.status!=='delivered').length;if(active>=4){toast('Conclua um dos quatro projetos em andamento antes de abrir outro.','warn',2400);openThiaguinhoStudio();return;}
    openModal('Novo projeto • Tipo',`<div class="dialogue-box"><b>1. Defina a solução</b><p>Escolha o tipo pelo problema que precisa resolver, não pela aparência.</p></div><div class="choice-grid">${Object.entries(DIGITAL_PROJECT_TYPES).map(([id,d])=>`<button class="choice" data-project-type="${id}"><b>${d.icon} ${d.name}</b><span>${d.summary}</span></button>`).join('')}</div>`,root=>{$$('[data-project-type]',root).forEach(btn=>btn.onclick=()=>openDigitalProjectClient(btn.dataset.projectType));});
  }
  function openDigitalProjectClient(type){const def=DIGITAL_PROJECT_TYPES[type];if(!def)return openThiaguinhoStudio();openModal('Novo projeto • Cliente',`<div class="dialogue-box"><b>2. Quem precisa da solução?</b><p>${def.icon} ${escapeHtml(def.name)} • escolha um cliente do universo do jogo.</p></div><div class="choice-grid">${DIGITAL_PROJECT_CLIENTS.map((c,i)=>`<button class="choice" data-project-client="${i}"><b>🏢 ${escapeHtml(c)}</b><span>Levantar necessidade e objetivo</span></button>`).join('')}</div>`,root=>{$$('[data-project-client]',root).forEach(btn=>btn.onclick=()=>openDigitalProjectGoal(type,DIGITAL_PROJECT_CLIENTS[Number(btn.dataset.projectClient)]));});}
  function openDigitalProjectGoal(type,client){const def=DIGITAL_PROJECT_TYPES[type];openModal('Novo projeto • Objetivo',`<div class="dialogue-box"><b>3. Qual problema será resolvido?</b><p>O objetivo vai orientar todas as decisões do projeto.</p></div><div class="choice-grid">${def.goals.map((g,i)=>`<button class="choice" data-project-goal="${i}"><b>🎯 ${escapeHtml(g)}</b><span>${escapeHtml(client)}</span></button>`).join('')}</div>`,root=>{$$('[data-project-goal]',root).forEach(btn=>btn.onclick=()=>createDigitalProject(type,client,Number(btn.dataset.projectGoal)));});}
  function createDigitalProject(type,client,goalIndex){const def=DIGITAL_PROJECT_TYPES[type];if(!def)return;const studio=ensureDigitalStudioState(),goal=def.goals[Math.max(0,Math.min(def.goals.length-1,goalIndex))],id=`proj-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`,project={id,type,client,goal,title:`${def.name} • ${client}`,phase:0,status:'active',quality:0,risks:0,decisions:[],tests:null,createdAt:Date.now(),updatedAt:Date.now()};studio.projects.push(project);studio.projects=studio.projects.slice(-12);studio.created=(studio.created||0)+1;studio.lastProjectAt=Date.now();state.stats.digitalProjects=(state.stats.digitalProjects||0)+1;saveState(true);openDigitalProject(id);}
  function digitalDecisionOptions(project){const def=DIGITAL_PROJECT_TYPES[project.type],phase=Number(project.phase||0),best=def.best[Math.min(2,phase)];if(phase===0)return[best,'Começar pelas telas mais bonitas antes de entender o problema.','Adicionar todas as funções possíveis sem priorizar o fluxo principal.'];if(phase===1)return[best,'Misturar interface, dados e regras em um único bloco para terminar rápido.','Duplicar telas para cada situação em vez de definir estados reutilizáveis.'];return[best,'Implementar várias funções ao mesmo tempo e testar somente no final.','Ignorar erros e responsividade enquanto a tela principal estiver abrindo.'];}
  function openDigitalProject(id){const p=digitalProjectById(id);if(!p)return openThiaguinhoStudio();const def=DIGITAL_PROJECT_TYPES[p.type]||DIGITAL_PROJECT_TYPES.pwa,phase=Number(p.phase||0),progress=Math.round((phase/5)*100);if(p.status==='delivered'){openModal('Projeto entregue',`<div class="lesson-result"><div>✅</div><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.goal)}</p><div class="resource-summary"><span>⭐ ${Math.round(p.quality||0)}% qualidade</span><span>🧪 ${p.tests?.passed||0}/${p.tests?.total||0} testes</span></div><button class="btn primary" data-digital-back>Voltar ao estúdio</button></div>`,root=>$('[data-digital-back]',root).onclick=openThiaguinhoStudio);return;}
    const phaseHtml=phase<3?`<div class="choice-grid">${digitalDecisionOptions(p).map((opt,i)=>`<button class="choice" data-project-decision="${i}"><b>${i===0?'🧠':'🛠️'} Decisão ${i+1}</b><span>${escapeHtml(opt)}</span></button>`).join('')}</div>`:phase===3?`<div class="choice-grid"><button class="choice" data-project-test><b>🧪 Executar matriz de testes</b><span>Funcionalidade, mobile, persistência, erros e performance</span></button>${p.tests&&!p.tests.approved?'<button class="choice" data-project-fix><b>🔧 Corrigir pendências</b><span>Revisar falhas antes de testar novamente</span></button>':''}</div>`:`<div class="choice-grid"><button class="choice" data-project-deliver><b>🚀 Entregar projeto</b><span>Fechar versão, registrar no portfólio e receber a avaliação</span></button></div>`;
    openModal(`${def.icon} ${p.title}`,`<div class="dialogue-box"><b>${escapeHtml(digitalPhaseName(phase))}</b><p>${escapeHtml(p.goal)}</p><div class="daily-progress"><i style="width:${progress}%"></i></div><small>Qualidade: ${Math.round(p.quality||0)}% • riscos: ${p.risks||0}</small></div>${phaseHtml}<div class="modal-actions"><button class="btn" data-digital-back>Voltar ao estúdio</button></div>`,root=>{
      $$('[data-project-decision]',root).forEach(btn=>btn.onclick=()=>applyDigitalDecision(id,Number(btn.dataset.projectDecision)));$('[data-project-test]',root)?.addEventListener('click',()=>runDigitalProjectTests(id));$('[data-project-fix]',root)?.addEventListener('click',()=>fixDigitalProject(id));$('[data-project-deliver]',root)?.addEventListener('click',()=>deliverDigitalProject(id));$('[data-digital-back]',root).onclick=openThiaguinhoStudio;
    });
  }
  function applyDigitalDecision(id,index){const p=digitalProjectById(id);if(!p||p.phase>=3)return;const options=digitalDecisionOptions(p),correct=index===0;p.decisions.push({phase:p.phase,choice:String(options[index]||''),best:correct,at:Date.now()});p.quality=clamp(Number(p.quality||0)+(correct?28:14),0,100);if(!correct)p.risks=Number(p.risks||0)+1;p.phase++;p.updatedAt=Date.now();addXP(correct?18:10);saveState(true);toast(correct?'Boa decisão de projeto.':'Funciona, mas adicionou risco técnico ao projeto.',correct?'good':'warn',2100);openDigitalProject(id);}
  function runDigitalProjectTests(id){const p=digitalProjectById(id);if(!p||p.phase!==3)return;const base=Math.round(p.quality||0),risks=Number(p.risks||0),checks=[['Fluxo principal',base>=45],['Mobile/responsividade',base>=55],['Persistência e recuperação',base-risks*6>=50],['Tratamento de erro',base-risks*8>=48],['Performance',base-risks*5>=52]],passed=checks.filter(x=>x[1]).length,approved=passed===checks.length;p.tests={total:checks.length,passed,approved,at:Date.now(),checks};if(approved){p.phase=4;p.quality=clamp(base+10,0,100);toast('Matriz aprovada. Projeto pronto para entrega.','good',2400);}else toast(`${passed}/${checks.length} testes passaram. Corrija as pendências.`, 'warn',2400);p.updatedAt=Date.now();saveState(true);openDigitalProject(id);}
  function fixDigitalProject(id){const p=digitalProjectById(id);if(!p||p.phase!==3)return;p.quality=clamp(Number(p.quality||0)+18,0,100);p.risks=Math.max(0,Number(p.risks||0)-1);p.tests=null;p.updatedAt=Date.now();addXP(8);saveState(true);toast('Pendências corrigidas. Execute novamente os testes.','good',1900);openDigitalProject(id);}
  function deliverDigitalProject(id){const p=digitalProjectById(id);if(!p||p.phase!==4||p.status==='delivered')return;const studio=ensureDigitalStudioState(),quality=Math.round(p.quality||0),reward=80+Math.round(quality*.8);p.status='delivered';p.deliveredAt=Date.now();p.updatedAt=Date.now();studio.delivered=(studio.delivered||0)+1;studio.portfolio.push({id:p.id,title:p.title,client:p.client,type:p.type,quality,deliveredAt:p.deliveredAt});studio.portfolio=studio.portfolio.slice(-20);state.stats.digitalDeliveries=(state.stats.digitalDeliveries||0)+1;addCoins(reward);addXP(40+Math.round(quality/4));addReputation(8+Math.round(quality/15));saveState(true);openModal('Projeto entregue!',`<div class="lesson-result"><div>🚀</div><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.client)} recebeu a solução.</p><div class="resource-summary"><span>⭐ ${quality}% qualidade</span><span>🪙 +${reward}</span><span>🏅 reputação +${8+Math.round(quality/15)}</span></div><button class="btn primary" data-digital-back>Voltar ao estúdio</button></div>`,root=>$('[data-digital-back]',root).onclick=openThiaguinhoStudio);}
  const WORKSHOP_PART_DEFS=Object.freeze([
    {id:'engine',name:'Motor',icon:'⚙️'},
    {id:'brakes',name:'Freios',icon:'🛑'},
    {id:'suspension',name:'Suspensão',icon:'🛞'},
    {id:'steering',name:'Direção',icon:'↔️'},
    {id:'electrical',name:'Elétrica / bateria',icon:'⚡'},
    {id:'cooling',name:'Arrefecimento',icon:'🌡️'}
  ]);
  function workshopVehicleList(){return(world.vehicles||[]).filter(v=>v?.id).map(v=>({vehicle:v,id:String(v.id),label:String(v.label||v.id),durability:typeof vehicleDurabilityV704==='function'?vehicleDurabilityV704(v):100,distance:Math.hypot(player.x-Number(v.group?.position?.x??v.x??0),player.z-Number(v.group?.position?.z??v.z??0))})).sort((a,b)=>a.durability-b.durability||a.distance-b.distance);}
