    if(delta>.5){const bias=workshopDamageBias(last.reason),sum=Object.values(bias).reduce((a,b)=>a+b,0)||1;for(const def of WORKSHOP_PART_DEFS){const weight=(bias[def.id]||.1)/sum,extra=delta*(.55+weight*2.8);record.parts[def.id]=clamp(Math.round(Number(record.parts[def.id]??100)-extra),0,100);}record.lastDamageAt=Number(last.at||Date.now());}
