  function workshopPartReport(vehicle){const record=workshopComponentRecord(vehicle);return WORKSHOP_PART_DEFS.map(def=>{const condition=clamp(Math.round(Number(record?.parts?.[def.id]??100)),0,100);return{...def,condition,status:condition<35?'CRÍTICO':condition<60?'DEFEITO':condition<82?'ATENÇÃO':condition<96?'DESGASTE':'OK',severity:condition<60?'bad':condition<96?'warn':'good'};});}
