  function athleticsTrackApproxLength(gym){const a=Math.max(gym.radiusX||26,gym.radiusZ||14),b=Math.min(gym.radiusX||26,gym.radiusZ||14);return Math.PI*(3*(a+b)-Math.sqrt((3*a+b)*(a+3*b)));}
